%[text] ## Local functions
function test = tRatioTest(X, opts)
    % tRatioTest__ParTI's t-ratio test of a SISAL triangle around the rows of X.
    %   As ParTI's findArchetypes: the points are rotated onto their principal
    %   components, each component is shuffled independently and SISAL refitted.
    %   The t-ratio is the triangle's area over the convex hull's; P is the
    %   fraction of shuffles with a smaller ratio than the data's.
    %
    %   Options
    %       Shuffles        (double, default 1000): Number of shuffles.
    %       Restarts        (double, default 150): SISAL runs for the data (ParTI: 3 x numIter).
    %       ShuffleRestarts (double, default 5): SISAL runs per shuffle (ParTI: numIter).
    %       Seed            (double, default 1): rng seed, set before the fit.
    %
    %   Example
    %       test = tRatioTest([mouse.avg.ID1, mouse.avg.ID2]);
    arguments
        X (:, 2) double
        opts.Shuffles (1,1) double {mustBeInteger, mustBePositive} = 1000
        opts.Restarts (1,1) double {mustBeInteger, mustBePositive} = 150
        opts.ShuffleRestarts (1,1) double {mustBeInteger, mustBePositive} = 5
        opts.Seed (1,1) double = 1
    end
    rng(opts.Seed);
    [~, pcs] = pca(X);
    [~, hull] = convhull(pcs);
    test.tRatio = MyPareto.fit(pcs, 3, Algorithm="sisal", Restarts=opts.Restarts).volume / hull;
    test.null = nan(opts.Shuffles, 1);
    for i = 1:opts.Shuffles
        shuffled = [pcs(randperm(height(pcs)), 1), pcs(randperm(height(pcs)), 2)];
        [~, hull] = convhull(shuffled);
        test.null(i) = MyPareto.fit(shuffled, 3, Algorithm="sisal", Restarts=opts.ShuffleRestarts).volume / hull;
    end
    test.p = mean(test.null < test.tRatio);
end

function plotPersonalitySpace(daily, avg, pareto, colors, opts)
    % plotPersonalitySpace__ID1-ID2 personality space drawn as Fig 5a, in raw ID units.
    %   One polygon per mouse spanning its daily scores and a dot at its mean, both
    %   colored by the mouse's weights in PARETO (means outside the triangle take
    %   the colors of its nearest side), and the triangle with colored vertices.
    %   Identity.PlotIDSpace z-scores by default, which would put the points and the
    %   triangle on different scales, so it is called with znorm off.
    %
    %   Options
    %       Reference (double, default []): Vertices of a second triangle, drawn dashed.
    %
    %   Example
    %       plotPersonalitySpace(mouse.daily, mouse.avg, mouse.pareto, opt.archetypeColors);
    arguments
        daily table                  % ID1, ID2 and MouseNumber, one row per mouse-day
        avg table                    % ID1, ID2 and MouseNumber, one row per mouse, sorted by MouseNumber
        pareto (1,1) MyPareto
        colors (3,3) double          % one RGB row per vertex
        opts.Reference (:,2) double = zeros(0, 2)
    end
    [mice, ~, mi] = unique(daily.MouseNumber);
    assert(isequal(mice, avg.MouseNumber), "avg must hold one row per mouse, sorted by MouseNumber");
    weights = max(pareto.weights([avg.ID1, avg.ID2]), 0);
    Identity.PlotIDSpace([daily.ID1, daily.ID2], daily.MouseNumber, 'znorm', false, ...
        'arcs', pareto.vertices, 'cmap', (weights ./ sum(weights, 2)) * colors, 'colorby', mi);
    hold on
    if ~isempty(opts.Reference)
        plot(opts.Reference([1:end 1], 1), opts.Reference([1:end 1], 2), "--", Color=[0.5 0.5 0.5], LineWidth=1.5);
    end
    scatter(pareto.vertices(:, 1), pareto.vertices(:, 2), 80, colors, "filled", MarkerEdgeColor="w");
    hold off
    set(gca, 'XTick', [-2 2], 'YTick', [-2 2], 'XTickLabel', ["-2" "2"], 'YTickLabel', ["-2" "2"]);
    set(gca, 'DataAspectRatio', [1 1 1], 'PlotBoxAspectRatioMode', 'auto');
    axis tight; xlim(xlim + [-0.3 0.3]); ylim(ylim + [-0.3 0.3]);
end

function c = cohortTable(daily, props, pareto)
    % cohortTable__One row per mouse: mean scores, readouts, weights, dominance and display group.
    %   ID and Behavior are means over the mouse's days; Weight holds its
    %   barycentric coordinates in PARETO (negative outside). David is the mean
    %   of the daily normalized David's score and Rank its order within the
    %   group (3 = alpha ... 0 = delta). Archetype is the display group: the k
    %   mice nearest each vertex, with the largest k that keeps the three sets
    %   disjoint (0 = not assigned).
    %
    %   Example
    %       c = cohortTable(alt.daily, props, mouse.pareto);
    arguments
        daily table                  % one row per mouse-day, with ID1, ID2 and the readouts
        props (1,:) cell             % names of the readouts
        pareto (1,1) MyPareto
    end
    [g, mouseNumber] = findgroups(daily.MouseNumber);
    c = table(mouseNumber, splitapply(@(x) x(1), daily.GroupNumber, g), VariableNames=["MouseNumber", "GroupNumber"]);
    c.ID = splitapply(@(x) mean(x, 1), [daily.ID1, daily.ID2], g);
    c.Behavior = splitapply(@(x) mean(x, 1, "omitnan"), daily{:, props}, g);
    c.Weight = pareto.weights(c.ID);
    c.David = splitapply(@(x) mean(x, "omitnan"), daily.NormalizedDavidScore, g);
    c.Rank = arrayfun(@(i) nnz(c.David(c.GroupNumber == c.GroupNumber(i)) < c.David(i)), (1:height(c))');
    [~, nearest] = sort(pdist2(c.ID, pareto.vertices), 1);
    k = find(arrayfun(@(k) numel(unique(nearest(1:k, :))) < 3 * k, 1:height(c)), 1) - 1;
    c.Archetype = zeros(height(c), 1);
    for a = 1:3
        c.Archetype(nearest(1:k, a)) = a;
    end
end

function [slope, p, r] = clusterSlope(y, x, group)
    % clusterSlope__OLS slope of y on x with cluster-robust (CR1) standard errors.
    %   p uses a t distribution with (number of clusters - 1) degrees of
    %   freedom; r is the Pearson correlation. Rows with NaN are dropped.
    %
    %   Example
    %       [b, p, r] = clusterSlope(c.David, c.Weight(:, 1), c.GroupNumber);
    arguments
        y (:,1) double
        x (:,1) double
        group (:,1)
    end
    ok = ~isnan(y) & ~isnan(x);
    y = y(ok);
    x = x(ok);
    [g, ~] = findgroups(group(ok));
    X = [ones(size(x)), x];
    bread = inv(X' * X);
    beta = bread * (X' * y);
    residual = y - X * beta;
    nClusters = max(g);
    meat = zeros(2);
    for j = 1:nClusters
        score = X(g == j, :)' * residual(g == j);
        meat = meat + score * score';
    end
    covariance = bread * meat * bread * (nClusters / (nClusters - 1)) * ((numel(y) - 1) / (numel(y) - 2));
    slope = beta(2);
    p = 2 * tcdf(-abs(slope / sqrt(covariance(2, 2))), nClusters - 1);
    r = corr(x, y);
end

function [r, p] = vertexProfile(behavior, weights, group)
    % vertexProfile__Pearson r and group-clustered p of every readout (column) against every vertex weight.
    arguments
        behavior (:,:) double
        weights (:,3) double
        group (:,1)
    end
    r = zeros(width(behavior), 3);
    p = zeros(width(behavior), 3);
    for a = 1:3
        for k = 1:width(behavior)
            [~, p(k, a), r(k, a)] = clusterSlope(behavior(:, k), weights(:, a), group);
        end
    end
end

function q = bhAdjust(p)
    % bhAdjust__Benjamini-Hochberg adjusted p-values; NaN entries are left out of the family.
    arguments
        p (:,1) double
    end
    q = nan(size(p));
    valid = find(~isnan(p));
    [sorted, order] = sort(p(valid));
    n = numel(sorted);
    q(valid(order)) = min(cummin(sorted .* n ./ (1:n)', "reverse"), 1);
end

function result = replicateProfile(referenceR, predicted, c, nPermutations)
    % replicateProfile__Agreement of a cohort's vertex profile with a reference profile, against block permutations.
    %   agreement is the share of PREDICTED associations whose r has the same
    %   sign in cohort C as in REFERENCER; correlation is Pearson's r between
    %   the two profiles over all associations. Each permutation hands the
    %   weights of whole groups to other groups, in random order within the
    %   group, so group mates stay together. P = (1 + permutations at least as
    %   large as observed) / (1 + permutations).
    %
    %   Example
    %       result = replicateProfile(profile.munich.r, profile.munich.q < 0.05, cohort.huji, 9999);
    arguments
        referenceR (:,3) double
        predicted (:,3) logical
        c table                      % from cohortTable
        nPermutations (1,1) double {mustBeInteger, mustBePositive}
    end
    agreement = @(r) mean(sign(r(predicted)) == sign(referenceR(predicted)));
    observed = corr(c.Behavior, c.Weight);
    result.agreement = agreement(observed);
    result.correlation = corr(referenceR(:), observed(:));
    [g, ~] = findgroups(c.GroupNumber);
    rowsOf = arrayfun(@(j) find(g == j), 1:max(g), UniformOutput=false);
    result.nullAgreement = zeros(nPermutations, 1);
    result.nullCorrelation = zeros(nPermutations, 1);
    rng(21);
    for i = 1:nPermutations
        donor = randperm(max(g));
        weights = zeros(size(c.Weight));
        for j = 1:max(g)
            from = rowsOf{donor(j)};
            weights(rowsOf{j}, :) = c.Weight(from(randperm(numel(from))), :);
        end
        r = corr(c.Behavior, weights);
        result.nullAgreement(i) = agreement(r);
        result.nullCorrelation(i) = corr(referenceR(:), r(:));
    end
    result.pAgreement = (1 + nnz(result.nullAgreement >= result.agreement)) / (1 + nPermutations);
    result.pCorrelation = (1 + nnz(result.nullCorrelation >= result.correlation)) / (1 + nPermutations);
end

function result = triangleShapeTest(scores, group, nShuffles)
    % triangleShapeTest__t-ratio of the smallest enclosing triangle against shuffled data.
    %   The t-ratio is the area of the smallest enclosing triangle
    %   (MyPareto.minEnclosingTriangle, a grid search over the two free side
    %   angles refined by fminsearch, so a numerical rather than a proven
    %   minimum) over the area of the convex hull. Resolution does not matter
    %   here: scoring observed data and shuffles at 90 or at 360 moves every
    %   t-ratio by less than 1e-12 and leaves P unchanged.
    %   nullAll shuffles column 2 across all rows; nullWithin shuffles it only
    %   within each group. P = (1 + shuffles with a ratio at least as small) /
    %   (1 + shuffles).
    %
    %   Example
    %       result = triangleShapeTest(cohort.huji.ID, cohort.huji.GroupNumber, 10000);
    arguments
        scores (:,2) double
        group (:,1) double
        nShuffles (1,1) double {mustBeInteger, mustBePositive}
    end
    COARSE = 90;   % grid resolution for the shuffles
    result.tRatio = tRatioOf(scores, 360);
    [g, ~] = findgroups(group);
    result.nullAll = zeros(nShuffles, 1);
    result.nullWithin = zeros(nShuffles, 1);
    rng(1);
    for i = 1:nShuffles
        result.nullAll(i) = tRatioOf([scores(:, 1), scores(randperm(height(scores)), 2)], COARSE);
        shuffled = scores;
        for j = 1:max(g)
            rows = find(g == j);
            shuffled(rows, 2) = scores(rows(randperm(numel(rows))), 2);
        end
        result.nullWithin(i) = tRatioOf(shuffled, COARSE);
    end
    result.pAll = (1 + nnz(result.nullAll <= result.tRatio)) / (1 + nShuffles);
    result.pWithin = (1 + nnz(result.nullWithin <= result.tRatio)) / (1 + nShuffles);

    function ratio = tRatioOf(points, resolution)
        [~, triangle] = MyPareto.minEnclosingTriangle(points, Resolution=resolution);
        hull = convhull(points(:, 1), points(:, 2));
        ratio = triangle / polyarea(points(hull, 1), points(hull, 2));
    end
end

function vertices = bootstrapVertices(scores, group, nBootstrap, reference)
    % bootstrapVertices__SISAL triangles of resamples of whole groups (3 x 2 x nBootstrap), ordered like REFERENCE.
    arguments
        scores (:,2) double
        group (:,1) double
        nBootstrap (1,1) double {mustBeInteger, mustBePositive}
        reference (3,2) double
    end
    [g, ~] = findgroups(group);
    rowsOf = arrayfun(@(j) find(g == j), 1:max(g), UniformOutput=false);
    vertices = zeros(3, 2, nBootstrap);
    for i = 1:nBootstrap
        rows = vertcat(rowsOf{randi(max(g), max(g), 1)});
        vertices(:, :, i) = MyPareto.fit(scores(rows, :), 3, Algorithm="sisal", Restarts=20).orderLike(reference).vertices;
    end
end

function treePlots(traits, behavior, meta, colors, titles, titleColors)
    % treePlots__One tree plot per column of TRAITS: its correlation with each readout (Identity.PlotID2BehaviorNewer).
    %   Bars are colored by the type of readout; only correlations that pass
    %   Bonferroni correction across the readouts are drawn.
    %
    %   Example
    %       treePlots(cohort.munich.ID, array2table(cohort.munich.Behavior(:, shown), VariableNames=behaviors), mouse.meta.behaviors, opt.colors, ["ID1", "ID2"]);
    arguments
        traits (:,:) double          % mice x traits
        behavior table               % mice x readouts
        meta table                   % readout metadata with name, type (categorical) and text
        colors (1,1) struct          % one RGB row per readout type
        titles (1,:) string
        titleColors (:,3) double = zeros(numel(titles), 3)
    end
    names = string(behavior.Properties.VariableNames);
    palette = cell2mat(arrayfun(@(type) colors.(type), string(categories(meta.type)), UniformOutput=false));
    tiledlayout(1, width(traits), TileSpacing="compact");
    ax = [];
    for i = 1:width(traits)
        ax(i) = nexttile; %#ok<AGROW>
        Identity.PlotID2BehaviorNewer(traits(:, i), behavior, colorBy=grp2idx(MyTables.asDict(meta(:, ["name", "type"]), names)), ...
            colormap=palette, labels=MyTables.asDict(meta(:, ["name", "text"]), names), verbose=false);
        title(titles(i), Color=titleColors(i, :));
    end
    MyFigure.mimicaxis(ax)
end

function exportPanel(name, opt)
    % exportPanel__Save the current figure to opt.outDir as PNG, vector PDF, SVG and vector EPS (when opt.saveFigures).
    %   The SVG is written by MyFigure.saveSVG, with live text and unsplit shapes.
    %   EPS cannot hold transparency, so the EPS is drawn from a copy of the
    %   figure in which every semi-transparent color is replaced by the solid
    %   color it shows on white (flattenAlpha); the PNG and PDF keep the
    %   transparency. The EPS is converted from a PDF with pdftocairo, which
    %   embeds the fonts; without pdftocairo MATLAB writes the EPS directly.
    arguments
        name (1,1) string
        opt (1,1) struct
    end
    if ~opt.saveFigures
        return
    end
    if ~isfolder(opt.outDir)
        mkdir(opt.outDir);
    end
    exportgraphics(gcf, fullfile(opt.outDir, name + ".png"), Resolution=300);
    exportgraphics(gcf, fullfile(opt.outDir, name + ".pdf"), ContentType="vector");
    MyFigure.saveSVG(gcf, fullfile(opt.outDir, name + ".svg"));

    flat = copyobj(gcf, groot);
    closeFlat = onCleanup(@() close(flat));
    flat.Visible = "off";
    flattenAlpha(flat);
    epsFile = fullfile(opt.outDir, name + ".eps");
    converters = ["/opt/homebrew/bin/pdftocairo", "/usr/local/bin/pdftocairo", "/usr/bin/pdftocairo"];
    converter = converters(find(isfile(converters), 1));
    if isempty(converter)
        exportgraphics(flat, epsFile, ContentType="vector");
    else
        opaquePdf = string(tempname) + ".pdf";
        exportgraphics(flat, opaquePdf, ContentType="vector");
        status = system(sprintf('"%s" -eps "%s" "%s"', converter, opaquePdf, epsFile));
        delete(opaquePdf);
        assert(status == 0, "pdftocairo failed for %s", name);
    end
end

function flattenAlpha(fig)
    % flattenAlpha__Replace every semi-transparent color in FIG by the solid color it shows on white.
    %   Covers faces and edges of patches, histograms and graph plots, scatter
    %   markers, grid lines and constant lines. Overlapping translucent shapes
    %   then cover each other instead of darkening, so flattened patches are
    %   moved below the other objects of their axes to keep markers visible, and
    %   the axis lines are drawn on top. A translucent white face is a veil over
    %   what lies beneath and is removed.
    %
    %   Example
    %       flat = copyobj(gcf, groot); flattenAlpha(flat);
    arguments
        fig (1,1) matlab.ui.Figure
    end
    solid = @(color, alpha) color .* alpha + (1 - alpha);
    isAlpha = @(h, prop) isprop(h, prop) && isnumeric(h.(prop)) && isscalar(h.(prop)) && h.(prop) < 1;
    isRGB = @(h, prop) isprop(h, prop) && isnumeric(h.(prop)) && size(h.(prop), 2) == 3;
    toBottom = gobjects(0);
    for h = findall(fig)'
        if isAlpha(h, "FaceAlpha")
            if isRGB(h, "FaceColor")
                if all(h.FaceColor == 1, "all")
                    h.FaceColor = "none";
                else
                    h.FaceColor = solid(h.FaceColor, h.FaceAlpha);
                    if isa(h, "matlab.graphics.primitive.Patch")
                        toBottom(end + 1) = h; %#ok<AGROW>
                    end
                end
            end
            h.FaceAlpha = 1;
        end
        if isAlpha(h, "EdgeAlpha")
            if isRGB(h, "EdgeColor")
                h.EdgeColor = solid(h.EdgeColor, h.EdgeAlpha);
            end
            h.EdgeAlpha = 1;
        end
        if isAlpha(h, "MarkerFaceAlpha")
            if isRGB(h, "MarkerFaceColor")
                h.MarkerFaceColor = solid(h.MarkerFaceColor, h.MarkerFaceAlpha);
            elseif isRGB(h, "CData")
                h.CData = solid(h.CData, h.MarkerFaceAlpha);
            end
            h.MarkerFaceAlpha = 1;
        end
        if isAlpha(h, "MarkerEdgeAlpha")
            if isRGB(h, "MarkerEdgeColor")
                h.MarkerEdgeColor = solid(h.MarkerEdgeColor, h.MarkerEdgeAlpha);
            end
            h.MarkerEdgeAlpha = 1;
        end
        if isa(h, "matlab.graphics.axis.Axes")
            h.GridColor = solid(h.GridColor, h.GridAlpha);
            h.GridAlpha = 1;
            h.MinorGridColor = solid(h.MinorGridColor, h.MinorGridAlpha);
            h.MinorGridAlpha = 1;
        end
        if isa(h, "matlab.graphics.chart.decoration.ConstantLine") && h.Alpha < 1
            h.Color = solid(h.Color, h.Alpha);
            h.Alpha = 1;
        end
    end
    for h = flip(toBottom)
        uistack(h, "bottom");
        set(ancestor(h, "axes"), Layer="top");   % the axis lines no longer show through the patches
    end
end

